<template><view class="comments"><view v-for="c in comments" :key="c.id" class="comment"><image class="avatar" :src="c.avatar||c.author?.avatar||'/static/ui/guest.svg'"/><view class="body"><text class="nickname">{{c.nickname||c.author?.nickname||'微信用户'}}</text><view class="date">{{date(c.timestamp)}}<text v-if="reply" @click="$emit('reply',c)">回复</text></view><rich-text :nodes="c.content" class="message"/></view><CrowIcon v-if="reply" class="comment-heart" name="like"/></view></view></template>
<script setup>import CrowIcon from './CrowIcon.vue';defineProps({comments:{type:Array,default:()=>[]},reply:Boolean});defineEmits(['reply']);const date=t=>{if(!t)return '';const d=new Date(t*1000);const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`}</script>
<style scoped>.comments{padding:45rpx 40rpx 90rpx}.comment{display:flex;gap:28rpx;margin-bottom:40rpx}.comment:last-child{margin-bottom:0}.avatar{height:70rpx;width:70rpx;flex-shrink:0;display:flex;align-items:center;justify-content:center;border-radius:50%;background:#f3f3f3;color:#cfcfcf;font-size:58rpx}.body{flex:1;min-width:0}.nickname{font-size:16px;line-height:1.6}.date{font-size:11px;color:#999;display:flex;gap:20rpx;line-height:1.4}.message{font-size:16px;font-weight:300;line-height:1.6;display:block;margin-top:20rpx}.comment-heart{font-size:22px;color:#ddd;margin-top:8rpx}</style>
